import{z as n,x as o,o as t,c as i,q as B,j as l,D as e,d as r,s,S as P,b as E}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"路径 MTU 发现","description":"","frontmatter":{"title":"路径 MTU 发现","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pmtud.md","filePath":"cs/pmtud.md","lastUpdated":1791413859000}'),C={name:"cs/pmtud.md"};function M(p,a,d,T,D,m){const A=o("Mermaid");return t(),i("div",null,[a[2]||(a[2]=B('<h1 id="路径-mtu-发现" tabindex="-1">路径 MTU 发现 <a class="header-anchor" href="#路径-mtu-发现" aria-label="Permalink to &quot;路径 MTU 发现&quot;">​</a></h1><div class="epigraph"><p>把 DF 置位，让太小的一跳用 ICMP 报告；过滤 ICMP 就把发现变成黑洞，主机只能靠探测或保守 1280/576。</p><footer>—— 据 RFC 1191；RFC 8201 IPv6 PMTUD；RFC 4821 分组化 PLPMTUD 整理</footer></div><p><a href="/cs/jumbo-mtu">巨帧</a> 与 <a href="/cs/gre-tunnels">GRE</a>、<a href="/cs/vxlan-overlay">VXLAN</a>、<a href="/cs/ipv6-transition">IPv6 过渡</a> 都吃 MTU。<a href="/cs/ipv6-transition">上一课</a> 留下隧道头税。缺口是<strong>沿路最小 MTU 怎么发现</strong>。本课不把 traceroute 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>源不知道路径。IPv4 PMTUD：DF=1，路由器丢弃并 ICMP Fragmentation Needed。IPv6 无源分片，只能这样。黑洞：中间丢大包且不回 ICMP（防火墙「安全」），TCP 卡住。PLPMTUD：传输层用探测与丢失推断，不依赖 ICMP。MSS 钳制后课会在边缘傻切，是权宜。</p><p>不要把 PMTUD 写成一次性：路由变化、ECMP 不同成员，最小 MTU 会变。</p><p><span class="marginnote">RFC 4821 针对黑洞。IPv6 最小链路 MTU 1280。本课不把每个 ICMP 代码背完。</span></p><p><span class="marginnote">DF 就是 Don&#39;t Fragment（不许分片）标志位：源在包上贴一张「不许半路拆散」的纸条。路由器装不下又不敢拆，只能把包扔掉并回一张 ICMP 通知——「这段路只有这么宽」。PMTUD 的全部机制就建立在这张回执上。</span></p><p><span class="marginnote">数字实例：以太网 MTU 1500，扣掉 IP 头 20 和 TCP 头 20，TCP 的 MSS 是 1460；中间套一层 VXLAN 隧道再吃掉约 50 字节头税后，路径有效 MTU 掉到 1450——源仍按 1500 发的包就会在隧道口被丢，这正是「头税」引爆 MTU 问题的典型场景。</span></p><h3 id="icmp-被滤则黑洞" tabindex="-1">ICMP 被滤则黑洞 <a class="header-anchor" href="#icmp-被滤则黑洞" aria-label="Permalink to &quot;ICMP 被滤则黑洞&quot;">​</a></h3><p>IPv6 必须发现。PLPMTUD 用传输探测。ECMP 与隧道使缓存失效。统一 MTU 可省掉发现。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：发大包 → ICMP → 降 MTU → 缓存。对照分片：中间分片与端到端发现，Saltzer 偏向端。隧道口应发 ICMP 或预先降低。</p>',13)),(t(),l(P,null,{default:e(()=>[s(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIG%5B%22DF%20%E5%A4%A7%E5%8C%85%22%5D%20--%3E%20DROP%5B%22%E4%B8%80%E8%B7%B3%E5%A4%AA%E5%B0%8F%22%5D%0A%20%20DROP%20--%3E%20ICMP%5B%22ICMP%20%E9%80%9A%E5%91%8A%20MTU%22%5D%0A%20%20ICMP%20--%3E%20CACHE%5B%22%E4%B8%BB%E6%9C%BA%E7%BC%93%E5%AD%98%22%5D%0A%20%20DROP%20--%3E%20BLK%5B%22%E6%97%A0%20ICMP%20%E5%88%99%E9%BB%91%E6%B4%9E%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"卫星与 5G 切片不改算法，只改 RTT，探测更慢。交换机巨帧不一致是二层版同一 bug。多播很少做 PMTUD，常用保守长度。安全：ICMP 可被伪造来缩小 MTU 做攻击，主机要合理性检查。",-1)),a[5]||(a[5]=E("p",null,"与容量无关：MTU 摊头税，不提高 \\(C\\)。",-1)),a[6]||(a[6]=E("p",null,"ICMP 被滤时，PLPMTUD 凭什么还能发现路径上限？两种发现方式的分岔如下。",-1)),(t(),l(P,null,{default:e(()=>[s(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%80%8E%E4%B9%88%E6%8E%A2%E5%87%BA%E8%B7%AF%E5%BE%84%E8%83%BD%E6%89%9B%E5%A4%9A%E5%A4%A7%E7%9A%84%E5%8C%85%EF%BC%9F%22%5D%20--%3E%20PM%5B%22%E7%BB%8F%E5%85%B8%20PMTUD%EF%BC%9A%E9%9D%A0%E8%B7%AF%E7%94%B1%E5%99%A8%E6%8A%A5%E4%BF%A1%22%5D%0A%20%20Q%20--%3E%20PL%5B%22PLPMTUD%EF%BC%9A%E9%9D%A0%E8%87%AA%E5%B7%B1%E7%9A%84%E4%B8%A2%E5%8C%85%E6%8E%A8%E6%96%AD%22%5D%0A%20%20PM%20--%3E%20P1%5B%22%E5%8F%91%20DF%20%E5%A4%A7%E5%8C%85%EF%BC%8C%E7%AD%89%20ICMP%20%E5%B8%A6%E5%9B%9E%E8%AF%A5%E8%B7%B3%20MTU%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E6%8C%89%E9%80%9A%E5%91%8A%E5%80%BC%E7%BC%A9%E5%8C%85%E5%B9%B6%E7%BC%93%E5%AD%98%22%5D%0A%20%20PL%20--%3E%20L1%5B%22%E4%BB%8E%E5%B0%8F%E5%B0%BA%E5%AF%B8%E8%B5%B7%E9%80%90%E6%AD%A5%E5%8A%A0%E5%A4%A7%E6%8E%A2%E6%B5%8B%E5%8C%85%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E6%8E%A2%E6%B5%8B%E5%8C%85%E4%B8%A2%E4%BA%86%EF%BC%9A%E9%80%80%E5%9B%9E%E4%B8%8A%E6%AC%A1%E7%A1%AE%E8%AE%A4%E8%BF%87%E7%9A%84%E5%80%BC%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E5%85%A8%E7%A8%8B%E4%B8%8D%E4%BE%9D%E8%B5%96%20ICMP%EF%BC%8C%E9%98%B2%E7%81%AB%E5%A2%99%E6%BB%A4%E6%8E%89%E4%B9%9F%E4%B8%8D%E6%80%95%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<p><span class="marginnote">常见误区：以为防火墙拦掉 ICMP 更安全。拦掉 Fragmentation Needed 这一类报错，等于把报信人灭口——大包悄悄消失、连接莫名卡死（黑洞），故障既难复现又不该发生。安全策略应放行这一类 ICMP，或直接改用 PLPMTUD。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IPv6 原子分片扩展头的全部争议。TTL 与 traceroute 是下一课。后课默认：路径 MTU 靠 ICMP 或传输探测；过滤 ICMP 要给发现留洞。</p><p>数据中心可全路径统一 9000，省掉发现，这是运营契约。</p><p>下一课<a href="/cs/ttl-traceroute">TTL 与 traceroute</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DF + ICMP 发现最小 MTU；IPv6 必须。</li><li>ICMP 被滤则黑洞，用 PLPMTUD。</li><li>隧道与 ECMP 使缓存失效。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 1191；RFC 8201；RFC 4821。</li></ul>',7))])}const c=n(C,[["render",M]]);export{I as __pageData,c as default};
